import assert from 'node:assert/strict';
import fs from 'node:fs/promises';

export async function runMotionDiagonalSmoke(page,kind){
 const cascade=kind==='iso-cascade',count=cascade?10:6,movementKey=cascade?'motion':'movement',sizeKey=cascade?'size':'cardSize',minimum=cascade?4:3,maximum=cascade?20:12;
 const previous=await page.evaluate(()=>({project:JSON.stringify(project),curPage,curSec,curEl,curPane,selection,secFocus,mode:NAGWEB_STORY_EDITOR.canvasMode(),timeline:NAGWEB_STORY_TIMELINE_UI.state()})),viewport=page.viewport();let revision=0;
 async function ready(total=count){await page.waitForFunction(total=>{const f=document.querySelector('.nw-motion-dialog iframe'),d=f?.contentDocument;return d?.querySelectorAll('.nw-diagonal-card').length===total&&d.querySelector('.nw-diagonal-surface')&&f.contentWindow.__NAG_SCROLL_DIRECTOR?.[d.querySelector('.sc')?.dataset.id]&&Array.from(d.querySelectorAll('[data-nw-stream-slot] img')).every(n=>n.complete&&n.naturalWidth>0);},{timeout:15000},total);}
 async function change(selector,value,total=count){const mark=String(++revision);await page.$eval(selector,(n,{value,mark})=>{document.querySelector('.nw-motion-dialog iframe').contentDocument.body.dataset.diagonalOld=mark;if(n.type==='checkbox')n.checked=value;else n.value=value;n.dispatchEvent(new Event('change',{bubbles:true}));},{value,mark});await page.waitForFunction(mark=>{const d=document.querySelector('.nw-motion-dialog iframe')?.contentDocument;return d?.body&&d.body.dataset.diagonalOld!==mark&&d.querySelector('.nw-diagonal-surface');},{timeout:10000},mark);await ready(total);}
 const control=key=>'[data-motion-stream="'+key+'"]';
 async function pose(progress,selector='.nw-motion-dialog iframe',gid){return page.$eval(selector,(f,{progress,gid})=>{const d=f.contentDocument;f.contentWindow.__NAG_SCROLL_DIRECTOR[gid||d.querySelector('.sc').dataset.id].set(progress);return Array.from(d.querySelectorAll('[data-nw-stream-slot]'),n=>({id:n.dataset.id,src:n.querySelector('img').src,instances:n.__nwMotionInstances,clip:n.__nwMotionClip,phase:n.dataset.nwStreamPhase}));},{progress,gid});}
 const geometry=cards=>cards.map(({phase,...n})=>n);
 try{
  await page.evaluate(()=>{project.pages[0].sections=[mkSection({layout:'free',sdEnabled:false,bg:'#527467',elements:[mkEl('label',{name:'Exterior',text:'Exterior'})]})];curPage=curSec=curEl=0;selection=[];secFocus=false;saveProject();renderPane();renderPreview();history=[];future=[];});const before=await page.evaluate(()=>JSON.stringify(project));
  await page.evaluate(()=>NAGWEB_MOTION_LAB.open());await page.click('[data-motion-template="'+kind+'"]');await ready();
  assert.equal(await page.$eval('[data-motion-stream-count]',n=>[+n.min,+n.max].join(',')),minimum+','+maximum);assert.equal(await page.$eval('[data-motion-config="duration"]',n=>+n.value),cascade?10:12);
  for(const [key,value] of [[sizeKey,cascade?'42':'40'],[movementKey,'continuous'],['direction',cascade?'up':'downRight'],['cardRatio','1:1'],['backgroundType','none']])assert.equal(await page.$eval(control(key),n=>n.value),value);
  const start=await pose(0);assert.deepEqual(geometry(start),geometry(await pose(1)));assert.notDeepEqual(geometry(start),geometry(await pose(.237)));assert.equal(await page.evaluate(()=>JSON.stringify(project)),before,'Template preview leaves the project untouched');
  await change(control(movementKey),'stepped');if(!cascade){assert.equal(await page.$eval('[data-stream-diagonal-steps]',n=>n.hidden),false);await change(control('stagger'),'100');await change(control(movementKey),'continuous');assert.equal(await page.$eval('[data-stream-diagonal-steps]',n=>n.hidden),true);await change(control(movementKey),'stepped');}
  await change('[data-motion-stream-count]',minimum,minimum);await change('[data-motion-stream-count]',count);assert.deepEqual((await pose(0)).map(n=>[n.id,n.src]),start.map(n=>[n.id,n.src]),'Removed positions recover their original content');await change('[data-motion-stream-count]',maximum,maximum);await change('[data-motion-stream-count]',minimum,minimum);
  await change(control(sizeKey),cascade?'25':'20',minimum);await change(control(cascade?'spacing':'overlap'),cascade?'20':'85',minimum);await change(control('cornerRadius'),'0',minimum);await change(control('shadow'),false,minimum);await change(control('frameRatio'),'auto',minimum);
  const colors=[[255,0,0],[0,255,0],[0,0,255],[255,255,0]].slice(0,minimum);
  await page.$eval('[data-motion-stream-batch-upload]',(input,colors)=>{const dt=new DataTransfer();colors.forEach((color,i)=>dt.items.add(new File(['<svg xmlns="http://www.w3.org/2000/svg" width="300" height="300"><rect width="300" height="300" fill="rgb('+color.join(',')+')"/></svg>'],'diagonal-'+i+'.svg',{type:'image/svg+xml'})));input.files=dt.files;input.dispatchEvent(new Event('change',{bubbles:true}));},colors);await page.waitForFunction(n=>document.querySelector('[data-motion-stream-batch-status]')?.textContent.includes('Se cargaron '+n),{},minimum);await ready(minimum);
  // Read actual rendered pixels and click through overlapping linked copies.
  for(const direction of cascade?['up','down','down-right','up-left']:['downRight','downLeft','upRight','upLeft']){
   await change(control('direction'),direction,minimum);await pose(.127);
   const probes=await page.$eval('.nw-motion-dialog iframe',(f,colors)=>{const d=f.contentDocument,host=d.querySelector('[data-nw-stream-slot]').offsetParent,canvas=host.querySelector('.nw-diagonal-surface'),nodes=Array.from(d.querySelectorAll('[data-nw-stream-slot]')),clip=nodes[0].__nwMotionClip,tiles=nodes.flatMap((n,slot)=>n.__nwMotionInstances.map(t=>({...t,id:n.dataset.id,slot}))).sort((a,b)=>b.depth-a.depth),inside=(poly,x,y)=>{let hit=false;for(let i=0,j=poly.length-1;i<poly.length;j=i++)if((poly[i].y>y)!==(poly[j].y>y)&&x<(poly[j].x-poly[i].x)*(y-poly[i].y)/(poly[j].y-poly[i].y)+poly[i].x)hit=!hit;return hit;},bySource=new Map(),fr=f.getBoundingClientRect(),hr=host.getBoundingClientRect();
    for(let y=clip.top+6;y<clip.top+clip.height-6;y+=6)for(let x=clip.left+6;x<clip.left+clip.width-6;x+=6){const hits=tiles.filter(t=>inside(t.polygon,x,y));if(new Set(hits.map(t=>t.id)).size<2)continue;const top=hits[0];let edge=Infinity;for(let i=0;i<4;i++){const a=top.polygon[i],b=top.polygon[(i+1)%4];edge=Math.min(edge,Math.abs((b.y-a.y)*x-(b.x-a.x)*y+b.x*a.y-b.y*a.x)/Math.hypot(b.y-a.y,b.x-a.x));}if(edge<3)continue;const list=bySource.get(top.id)||[];if(list.some(p=>p.depth===top.depth))continue;list.push({id:top.id,depth:top.depth,expected:colors[top.slot],pixel:Array.from(canvas.getContext('2d').getImageData(Math.floor(x/host.clientWidth*canvas.width),Math.floor(y/host.clientHeight*canvas.height),1,1).data),x:fr.left+(hr.left+x)*fr.width/f.clientWidth,y:fr.top+(hr.top+y)*fr.height/f.clientHeight});bySource.set(top.id,list);if(list.length===2)return list;}
    return Array.from(bySource.values())[0]||[];},colors);
   assert.ok(probes.length,'There are selectable overlapping cards');for(const p of probes){assert.equal(p.pixel[3],255);p.expected.forEach((v,i)=>assert.ok(Math.abs(v-p.pixel[i])<4,JSON.stringify(p)));await page.mouse.click(p.x,p.y);assert.equal(await page.$eval('[data-motion-layer="'+p.id+'"]',n=>n.getAttribute('aria-pressed')),'true');}
  }
  const textureCache=await page.$eval('.nw-motion-dialog iframe',f=>{const d=f.contentDocument,rt=f.contentWindow.__NAG_SCROLL_DIRECTOR[d.querySelector('.sc').dataset.id],native=d.createElement;let created=0;d.createElement=function(tag,...args){if(tag==='canvas')created++;return native.call(this,tag,...args);};try{for(let i=0;i<40;i++)rt.set(i/40);created=0;for(let i=0;i<40;i++)rt.set(i/40);return created;}finally{d.createElement=native;}});assert.equal(textureCache,0);
  await change(control('direction'),cascade?'up':'downRight',minimum);await change(control('cardRatio'),'3:4',minimum);await change(control('backgroundType'),'gradient',minimum);await change('[data-motion-config="source"]','scroll',minimum);for(const [k,v] of [['turns','3'],['start','20'],['end','80'],['scrollLength','420']])await change(control(k),v,minimum);assert.equal((await pose(.5))[0].phase,'1.500000');assert.equal(await page.evaluate(()=>JSON.stringify(project)),before);
  await page.click('[data-motion-library-tab="library"]');await page.$eval('[data-motion-library-name]',(n,kind)=>n.value='Mi '+kind,kind);await page.click('[data-motion-library-save]');const saved=await page.evaluate(()=>project.nwMotionLibrary.at(-1));assert.equal(saved.config.stream.kind,kind);await page.click('[data-motion-saved="'+saved.id+'"]');await ready(minimum);await page.click('[data-motion-insert-group]');const inserted=await page.evaluate(()=>{const g=sec().elements.find(e=>e.nwMotionInstance);return{gid:g.id,project:JSON.stringify(project),config:g.nwMotionInstance,outside:sec().elements[0].text};});assert.equal(inserted.config.stream.kind,kind);assert.equal(inserted.outside,'Exterior');assert.equal(inserted.config.stream.cardRatio,'3:4');
  await page.evaluate(()=>{const f=document.createElement('iframe');f.id='diagonal-export';f.style.cssText='width:1280px;height:720px';f.srcdoc=generateSite(flattenPage(page()),false,false,false);document.body.append(f);});await page.waitForFunction(gid=>document.querySelector('#diagonal-export')?.contentWindow?.__NAG_SCROLL_DIRECTOR?.[gid]&&document.querySelector('#diagonal-export').contentDocument.querySelector('.nw-diagonal-surface'),{},inserted.gid);const output=await pose(.5,'#diagonal-export',inserted.gid);assert.equal(output[0].phase,'1.500000');assert.ok(output.some(n=>n.instances.length));
  await page.$eval('#diagonal-export',(f,gid)=>{f.contentWindow.__NAG_SCROLL_DIRECTOR[gid].live();f.contentWindow.scrollTo(0,f.contentDocument.querySelector('.sc').offsetHeight/2-f.contentWindow.innerHeight/2);},inserted.gid);await page.waitForFunction(gid=>document.querySelector('#diagonal-export').contentWindow.__NAG_SCROLL_DIRECTOR[gid].progress()>.4,{},inserted.gid);
  await page.evaluate(id=>NAGWEB_MOTION_LAB.edit(id),inserted.gid);await ready(minimum);assert.equal(await page.$eval(control('cardRatio'),n=>n.value),'3:4');await change('[data-motion-config="source"]','time',minimum);await change('[data-motion-config="duration"]','2',minimum);await page.click('[data-motion-save]');const edited=await page.evaluate(()=>JSON.stringify(project));await page.evaluate(()=>undo());assert.equal(await page.evaluate(()=>JSON.stringify(project)),inserted.project);await page.evaluate(()=>redo());assert.equal(await page.evaluate(()=>JSON.stringify(project)),edited);assert.equal(await page.evaluate(gid=>migrate(JSON.parse(JSON.stringify(project))).pages[0].sections[0].elements.find(e=>e.id===gid).nwMotionInstance.stream.kind,inserted.gid),kind);
  await page.setViewport({width:390,height:844,deviceScaleFactor:1});await page.evaluate(()=>NAGWEB_MOTION_LAB.open());await page.click('[data-motion-template="'+kind+'"]');await ready();await change(control('frameRatio'),'auto');await pose(.317);await fs.mkdir('/tmp/nagweb-motion-visuals',{recursive:true});await (await page.$('.nw-motion-dialog')).screenshot({path:'/tmp/nagweb-motion-visuals/'+kind+'-mobile.png'});await page.emulateMediaFeatures([{name:'prefers-reduced-motion',value:'reduce'}]);assert.deepEqual(await pose(.1),await pose(.9));await page.emulateMediaFeatures([]);await page.click('[data-motion-close]');assert.equal(await page.evaluate(()=>JSON.stringify(project)),edited);
  console.log(kind+': controls, directions, real pixels and overlap selection, uploads, count recovery, texture reuse, draft isolation, library, insertion/reopen, history, JSON, real scroll/export, mobile and reduced motion OK');
 }catch(error){await fs.mkdir('/tmp/nagweb-motion-visuals',{recursive:true});await page.screenshot({path:'/tmp/nagweb-motion-visuals/'+kind+'-failure.png'}).catch(()=>{});throw error;}finally{await page.emulateMediaFeatures([]);await page.setViewport(viewport);await page.evaluate(p=>{document.querySelector('.nw-motion-dialog').close();document.querySelector('#diagonal-export')?.remove();clearTimeout(previewTimer);project=JSON.parse(p.project);curPage=p.curPage;curSec=p.curSec;curEl=p.curEl;curPane=p.curPane;selection=p.selection;secFocus=p.secFocus;history=[];future=[];NAGWEB_STORY_EDITOR.setCanvasMode(p.mode);NAGWEB_STORY_TIMELINE_UI.setState(p.timeline);saveProject();renderScenes();renderPane();renderPreview();},previous);}
}
